// Pega o ID do chat. O teste de debug anterior (fd08bf.png) mostrou
// que o ID do chat vem em msg.payload.chatId
let chatId = msg.payload.chatId;

// Pega o objeto de usuários
let usuarios = global.get("usuarios") || {};

// Adiciona o usuário com um "estágio"
usuarios[chatId] = {
    id: chatId,
    stage: "awaiting_frequency"
};

global.set("usuarios", usuarios);

msg.payload = {
    chatId: chatId,
    type: 'message',
    content: "Olá! Bem-vindo ao monitor de consumo de água. 💧\n\nCom que frequência você quer receber relatórios? Escolha uma opção:\n\n(1) - DIARIO\n(2) - SEMANAL\n(3) - MENSAL"
};

return msg;

let usuarios = global.get("usuarios") || {};
let chatId = msg.payload.chatId;
let user = usuarios[chatId];

let resposta = "";

if (user && user.stage === "awaiting_frequency") {
    let opcao = msg.payload.content;
    let frequencia = "";

    if (opcao == 1) frequencia = "DIARIA";
    else if (opcao == 2) frequencia = "SEMANAL";
    else if (opcao == 3) frequencia = "MENSAL";

    user.frequency = frequencia;
    user.stage = "registered"; // Cadastro completo!

    global.set("usuarios", usuarios); // Salva a atualização

    resposta = `Pronto! Sua frequência foi definida como *${frequencia}*. Você receberá seu primeiro relatório em breve.`;

} else {
    resposta = "Não entendi. Digite */start* para começar.";
}

msg.payload = {
    chatId: chatId,
    type: 'message',
    content: resposta
};

return msg;

// A função irá realizar o cálculo estimado...
function calcularFaturaSabesp(litrosTotais) {
    let m3 = litrosTotais / 1000.0;
    if (m3 <= 10) { return 75.92; }
    let custo = 0;
    custo += 75.92;
    if (m3 <= 20) {
        let m3_faixa2 = m3 - 10;
        custo += m3_faixa2 * 5.99;
    } else {
        custo += (10 * 5.99);
        if (m3 <= 50) {
            let m3_faixa3 = m3 - 20;
            custo += m3_faixa3 * 11.82;
        } else {
            custo += (30 * 11.82);
            let m3_faixa4 = m3 - 50;
            custo += m3_faixa4 * 13.00;
        }
    }
    return custo;
}

// Aqui será gerado o relatório de consumo
let usuarios = global.get("usuarios") || {};
let leituras = global.get("leiturasAgua") || [];
let hoje = new Date().getDay();
let diaDoMes = new Date().getDate();

let consumoPeriodo = leituras.reduce((total, leitura) => {
    return total + parseFloat(leitura.litros || 0);
}, 0);
let consumoMensalAtual = global.get("consumoMensal") || 0;
let consumoMensalAnterior = consumoMensalAtual - consumoPeriodo;
let custoTotalAtual = calcularFaturaSabesp(consumoMensalAtual);
let custoTotalAnterior = calcularFaturaSabesp(consumoMensalAnterior);
let custoAproximadoDoPeriodo = custoTotalAtual - custoTotalAnterior;

for (let userId in usuarios) {
    let user = usuarios[userId];
    let enviarHoje = false;

    if (user.frequency === 'DIARIO') enviarHoje = true;
    else if (user.frequency === 'SEMANAL' && hoje === 1) enviarHoje = true;
    else if (user.frequency === 'MENSAL' && diaDoMes === 1) enviarHoje = true;

    if (enviarHoje) {

        let mensagemIncentivo = (consumoPeriodo > 150) ? "Seu consumo foi alto! 😟" : "Parabéns! Seu consumo está eficiente. 👏";

        let relatorio = `--- 📊 Relatório de Consumo 📊 ---\n\n💧 Consumo (Período): ${consumoPeriodo.toFixed(2)} Litros\n💸 Custo (Período): R$ ${custoAproximadoDoPeriodo.toFixed(2)}\n📈 Acumulado do Mês 📈\nTotal no Mês: ${(consumoMensalAtual / 1000).toFixed(2)} m³\nFatura Parcial: R$ ${custoTotalAtual.toFixed(2)}\n\n${mensagemIncentivo}`;

        node.send({
            payload: {
                chatId: user.id,
                type: 'message',
                content: relatorio
            }
        });
    }
}

// Limpando as leituras do período
global.set("leiturasAgua", []);

return null;

msg.payload = {
    chatId: msg.payload.chatId,
    type: 'message',
    content: "Desculpe, não entendi esse comando. Digite */start* para começar."
};
return msg;

// Coletando o objeto de dados que vem do Arduino
// msg.payload = {"vazao": 5.0}
let dadosDoArduino = msg.payload;

// Valida se a propriedade vazão existe e se é um número
if (typeof dadosDoArduino.vazao !== 'number') {
    node.warn("Payload recebido não tem 'vazao' ou não é um número.");
    return null;
}

// Pega a vazão (Litros por Minuto)
let vazao_L_min = dadosDoArduino.vazao;

// Converte a TAXA (L/min) para o VOLUME (Litros) daquele segundo
let leituraNumero = vazao_L_min / 60.0;

// Salva histórico local
let leituras = global.get("leiturasAgua") || [];
leituras.push({
    timestamp: new Date(),
    litros: leituraNumero
});
global.set("leiturasAgua", leituras);

// Soma no total mensal
let consumoMensal = global.get("consumoMensal") || 0;
consumoMensal += leituraNumero;
global.set("consumoMensal", consumoMensal);

// Formata para InfluxDB 
msg.payload = {
    litros_segundo: leituraNumero, // O consumo naquele segundo
    consumo_m3: leituraNumero / 1000,
    vazao_L_min: vazao_L_min // A vazão L/min original
};

msg.tags = {
    sensor: "arduino_principal"
};

return msg;

function calcularFaturaSabesp(litrosTotais) {
    let m3 = litrosTotais / 1000.0;
    if (m3 <= 10) return 75.92;
    let custo = 75.92;
    if (m3 <= 20) custo += (m3 - 10) * 5.99;
    else if (m3 <= 50) custo += (10 * 5.99) + ((m3 - 20) * 11.82);
    else custo += (10 * 5.99) + (30 * 11.82) + ((m3 - 50) * 13.00);
    return custo;
}

// Pegando o mês de referência da fatura
let dataHoje = new Date();
// Pega o mês (0-11) + 1 para ficar (1-12) e formata com zero à esquerda
let mes = (dataHoje.getMonth() + 1).toString().padStart(2, '0');
let ano = dataHoje.getFullYear();
let referenciaFormatada = `${ano}-${mes}`;

// --- Pega o consumo total do mês ---
let consumoMensalFechado = global.get("consumoMensal") || 0;
let custoTotalFechado = calcularFaturaSabesp(consumoMensalFechado);

// --- Cria registro no formato do InfluxDB ---
msg.payload = {
    consumo_litros: consumoMensalFechado,
    consumo_m3: consumoMensalFechado / 1000.0,
    custo_total: custoTotalFechado,
    mes_referencia: referenciaFormatada
};

// --- Zera contador ---
global.set("consumoMensal", 0);

return msg;
